const N:usize=9;const Q:usize=24;const R:usize=4;
fn put(out:[*]u8,at:usize,x:i64) void {const b:u64=@bitCast(x);for(0..8)|i|out[at+i]=@truncate(b>>@intCast(8*i));}
fn owned(g:*const [81]bool,level:*const [9]i64,n:usize,u:usize,list:*[9]usize) usize {var z:usize=0;for(0..n)|v|{if(g[u*N+v] and level[u]==0 and level[v]==0){list[z]=v;z+=1;}}return z;}
fn repair(g:*const [81]bool,level:*const [9]i64,mate:*[9]i64,n:usize,u:i64) void {if(u<0)return;const z:usize=@intCast(u);if(level[z]!=0 or mate[z]>=0)return;for(0..n)|v|{if(g[z*N+v] and level[v]==0 and mate[v]<0){mate[z]=@intCast(v);mate[v]=@intCast(z);return;}}}
fn promote(g:*const [81]bool,level:*[9]i64,mate:*[9]i64,n:usize,u:usize,tape:*const [4]usize,r:usize,used:*usize) bool {var list=[_]usize{0}**N;const count=owned(g,level,n,u,&list);if(count==0 or used.*>=r or tape[used.*]>=count)return false;const y=list[tape.*[used.*]];used.*+=1;const w=mate[u];const x=mate[y];if(w>=0){mate[@intCast(w)]=-1;mate[u]=-1;}if(x>=0){mate[@intCast(x)]=-1;mate[y]=-1;}level[u]=1;level[y]=1;mate[u]=@intCast(y);mate[y]=@intCast(u);repair(g,level,mate,n,w);if(x!=w)repair(g,level,mate,n,x);return true;}
export fn two_level_dynamic_maximal_matching_insertions(input_opt:?[*]const i64,length:usize,output_opt:?[*]u8,capacity:usize)i64{
 if(input_opt==null or length<3 or length>55)return -1;const in=input_opt.?;const n0=in[0];const q0=in[1];if((n0!=4 and n0!=9) or q0<0 or q0>24 or q0>n0*(n0-1)/2)return -1;const n:usize=@intCast(n0);const q:usize=@intCast(q0);var us=[_]usize{0}**Q;var vs=[_]usize{0}**Q;var seen=[_]bool{false}**81;var p:usize=2;
 for(0..q)|e|{const u64=in[p];const v64=in[p+1];p+=2;if(u64<0 or v64<=u64 or v64>=n0)return -1;const u:usize=@intCast(u64);const v:usize=@intCast(v64);if(seen[u*N+v])return -1;seen[u*N+v]=true;us[e]=u;vs[e]=v;}
 if(p>=length)return -1;const r64=in[p];p+=1;if(r64<0 or r64>4 or length!=p+@as(usize,@intCast(r64)))return -1;const r:usize=@intCast(r64);var tape=[_]usize{0}**R;for(0..r)|i|{const x=in[p+i];if(x<0 or x>=n0)return -1;tape[i]=@intCast(x);}
 var graph=[_]bool{false}**81;var level=[_]i64{0}**N;var mate=[_]i64{-1}**N;var used:usize=0;const threshold:usize=if(n==4)2 else 3;
 for(0..q)|e|{const u=us[e];const v=vs[e];graph[u*N+v]=true;graph[v*N+u]=true;if(level[u]==1 or level[v]==1)continue;if(mate[u]<0 and mate[v]<0){mate[u]=@intCast(v);mate[v]=@intCast(u);}var temp=[_]usize{0}**N;const du=owned(&graph,&level,n,u,&temp);const dv=owned(&graph,&level,n,v,&temp);const who=if(du>dv or (du==dv and u<v))u else v;const cnt=owned(&graph,&level,n,who,&temp);if(cnt>=threshold and !promote(&graph,&level,&mate,n,who,&tape,r,&used))return -1;}
 if(used!=r)return -1;const bytes=8*(1+2*n);if(output_opt==null or capacity<bytes)return -2;const out=output_opt.?;put(out,0,@intCast(n));for(0..n)|i|put(out,8+8*i,level[i]);for(0..n)|i|put(out,8+8*n+8*i,mate[i]);return @intCast(bytes);
}
